-- disclosure_documents: 5 条记录
INSERT INTO disclosure_documents (id, case_id, content_json, ai_suggestions, status, version, created_at, updated_at) VALUES ('267d53f5-7cfa-4604-b0b4-403c43781ee6', 'c78fc3fc-2f17-41f9-a113-9c1f721550af', '{"title":"智能温控系统","background":"现有温控系统效率低"}', '[]', 'draft', 1, '2026-05-17T06:22:56.260Z', '2026-05-17T06:22:56.260Z');
INSERT INTO disclosure_documents (id, case_id, content_json, ai_suggestions, status, version, created_at, updated_at) VALUES ('542748a9-84a1-4dde-ba82-9df83710e22d', '4d8eced9-7f93-4bc8-8a7b-b23749d2dc32', '{"title":"一种新型半轴装配用吊具","content":"技 术 交 底 书\\n\\n专利名称：  一种新型半轴装配用专用吊具           （实用新型）\\n交底问题联系人：                                             \\n联系方式：               邮箱：               \\n术语解释：吊具：是一种起吊装置，能将所需装配的工件协助吊起转运或装配。                         \\n一、本发明/实用新型解决的技术问题是：\\n本实用新型适应于各种重卡驱动桥半轴的起吊装配，涉及各类城市客车、货车等使用的驱动桥；    \\n本实用新型1、吊具以半轴法兰盘的外端面+法兰盘孔为定位，避免半轴、滑落偏移，造成损伤。2、半轴吊装过程中，通过吊钩勾住半轴轴径部位，在吊取过程中避免半轴一侧偏重导致滑落，造成损伤；3、吊具与半轴法兰盘先配合定位，避免半轴吊装过程中出现不平稳现象。4、工装便捷轻巧，吊环螺钉+可旋转式滑块组件操作更便捷，省时省力。\\t\\n二、详细介绍技术背景，并描述已有的与本发明/实用新型最相近似的实现方案。\\n现阶段，车桥半轴装配有采用定位夹盘装置夹住半轴法兰盘、然后通过支撑法兰盘的方式，起吊转运进行桥总成装配，不仅起吊平稳性差，而且容易脱落对车桥半轴磕碰、破坏及工人安全的风险；原有吊具受零部件结构的影响，设计单一且使用不便捷，无法轻松起吊半轴。现阶段，市场竞争激烈，节能降本，越来越受到重视，在保证工装使用性能的前提下，提高工装的通用性、降低劳动强度是保证工装先进性的重要方面。\\n\\t\\n三、现有技术的缺点是什么？针对这些缺点，说明本发明/实用新型的目的。\\n1、现有车桥半轴装配，以人工手动搬取，装配过程中存有半轴滑落的风险，影响装配过程中工人的安全；\\n2、现阶段以人工搬运装配的方式，在装配过程中半轴如果工人失力，导致半轴装配偏离撞击轮端，则会影响车桥其余零部件的质量及寿命；\\n本实用新型目的：1、保证车桥半轴在装配过程中不会滑落、偏移，不影响后续装配；\\n2、操作便捷，省时省力，极大的提高操作安全性。\\t\\n四、本发明/实用新型技术方案的详细阐述：\\n\\n附图说明\\n下面结合附图和实施例对本实用新型进一步说明。\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n     \\n图1 本实用新型的三维结构示意图\\n\\n\\n图2 本实用新型的工作台结构示意图\\n1、挂杆组件，2、滑块组件（滑块组件具体配合结构），3、吊钩，4、吊环螺钉，5、开口销 \\n具体实施方式\\n下面结合附图对该实用新型进行进一步描述：\\n1、本实用新型半轴吊具工装由挂杆配合半轴法兰盘及法兰盘孔，吊钩用来勾住半轴轴径，保证半轴吊起转运装配过程中稳定、平衡；\\n2、使用时，操作者拿着挂杆组件将其弯钩处穿入半轴法兰盘孔中，使吊具和半轴进行初步定位；\\n3、操作者手扶半轴法兰盘将半轴抽出，直至半轴轴承漏出一半，然后将吊钩旋转勾住半轴轴径，操作者操作KPK将半轴吊起，进行转运并装配；\\n4、本实用新型车桥半轴起吊工装利用半轴法兰盘的支撑及定位，保证半轴在整个起吊过程中的定位及平稳，降低工人劳动强度，在批量生产过程中，保证零部件的质量、状态不被人工搬运过程影响。\\n\\n\\n\\n\\n\\t\\n五、本发明/实用新型的关键点和欲保护点是：\\n1、通过法兰盘和半轴轴部两处吊点进行吊运，吊转过程平衡；\\n2、吊半轴轴部采用可旋转式吊钩；\\n\\t\\n六、与第二条所属的最好的现有技术相比，本发明/实用新型的优点：\\n1、保证半轴起吊过程平稳，避免半轴吊转过程中滑移、脱落；\\n2、对操作者装配过程有一定的保护作用，降低了装配过程中工人损伤的安全风险；\\n3、操作更便捷，无需人工搬运，安全性更高。\\t\\n七、针对第四部分中的技术方案，是否还有别的替代方案？\\n1、可将件1转化为弓形结构，件1与件2通过上部连接到一起，使吊装重心稳定至吊具中心位置；\\n2、件3吊钩可替换为环形夹具夹住轴部；\\n\\t\\n八、其他有助于专利代理人理解本技术的资料：\\n\\t\\n【注意】\\n代理人并不是技术专家，交底书需要尽量使代理人看懂，特别对于背景技术和详尽的技术方案，\\n对同一事物的叫法应统一，避免出现一种东西多种叫法。\\n沟通时，对于代理人的疑问应认真理解，要求补充的材料应及时补充。\\n专利法规定：\\n①专利必须是一个技术方案，应该阐述发明（实用新型）目的是通过什么技术方案来实现的，不能只有原理，也不能只做功能介绍；\\n交底书不能按功能写，应按步骤/层次写，即从步骤/层次角度扩展（以阶梯方式描述），使之逻辑清楚。若从功能角度写，则具有较多的介绍成分，使本发明（实用新型）的方法/系统分散，不易提炼本发明（实用新型）的核心。\\n②专利必须充分公开，以本领域技术人员不需付出创造性劳动即可实现为准。\\n"}', '[]', 'approved', 1, '2026-05-18T08:21:58.226Z', '2026-05-18T08:21:58.226Z');
INSERT INTO disclosure_documents (id, case_id, content_json, ai_suggestions, status, version, created_at, updated_at) VALUES ('889571f1-04bf-4ba5-9dc3-7b00d64d3887', '523aea0c-da59-4055-8909-d77e3bef4d47', '{"title":"一种用于检测ABS传感器夹持拉脱力的测试试验台","content":"技 术 交 底 书\\n\\n专利名称： 一种用于检测ABS传感器夹持拉脱力的测试试验台 （发明专利）\\n交底问题联系人：            \\n联系方式：             邮箱：                 \\n术语解释：                                                        \\n一、本发明/实用新型解决的技术问题是：\\n1、一种用于多个种类ABS传感器夹持时拉脱力的测试试验台。\\n2、适用于ABS传感器和传感器支架夹持配合时，拉脱传感器所需拉脱力的测试工作；\\n3、解决并避免了采用人工拉拽来进行检测ABS传感器夹持时拉脱力时的工伤隐患。\\t\\n二、详细介绍技术背景，并描述已有的与本发明/实用新型最相近似的实现方案。\\n1、现有的后桥总成的ABS传感器，安装时需紧固在传感器支架上，为保证ABS传感器夹持在传感器支架上能够长期有效，现有方案是利用钣金衬套的轴向形变和传感器支架内壁的摩擦来保持预紧，为便于检验，其钣金衬套和传感器支架的预紧夹持力通常以ABS传感器拉脱时的拉脱力来进行量化，要求为100-120N。测试摩擦预紧力\\n2、本案公开一种适用于多平台、多种规格ABS传感器夹持拉脱力的测试试验台。\\t\\n三、现有技术的缺点是什么？针对这些缺点，说明本发明/实用新型的目的。\\n现有的检验方法为人工检验，同时在传感器末端和弹簧秤的末端都绑上铁丝，两铁丝交互缠绕，两位检验员进行对拉，然后第三位检验员在旁边进行读数；如下图：\\n          \\n 该方法有众多弊端：首先，耗费人力及工时。每次检验传感器拉脱力需3名检验人员同时操作，尤其是批量进货检测时人工耗费量大。其次，操作效率低。传感器和弹簧秤末端为铁丝捆绑，手工缠绕，操作效率太低。再次，存在工伤风险。铁丝捆绑时操作人员易划伤手臂，检验员进行对拉读取弹簧秤数值时，若零部件不合格，传感器会猛然脱出，导致检验人员摔伤。\\n因此，设计一种能够适用于多个平台、多种规格ABS传感器夹持力及拉脱力的自动测试试验台成为亟待解决的问题。\\t\\n四、本发明/实用新型技术方案的详细阐述：\\n本专利所采用的技术方案：\\n以传感器支架安装座（件02）为固定基准，以气缸（件04）、导轨及滑块总成（件06）为滑动单元，弹簧秤安装支座（件05）同时连接气缸及导轨滑块，以气缸固定支架（件03）为支撑，令其能够沿着导轨进行直线滑动。\\n以ABS固定板（件10）及连接板（件11）替代连接传感器末端和弹簧秤的铁丝； ABS固定板设计为冲压零部件，其冲压形状上下安装后能够卡住传感器末端；ABS固定板（件10）及连接板（件11）以M8的螺栓螺母连接。\\n推钳总成（件07）、树脂垫块（件07）及防护盖板（件12）为选装零部件，其作用为防止零部件不合格，传感器脱出时伤及检验人员。\\n\\n本技术方案具体实施如下（结合附图）：\\n  \\n1、ABS传感器（带衬套）与传感器支架反装，通过螺栓固定在传感器支架安装座02上，将ABS固定板（件10）及连接板（件11）以M8的螺栓连接，与弹簧秤末端安装好。\\n2、通过调节气缸固定支架（件03）左右位置，令弹簧秤上端与弹簧秤安装支座（件05）的挂钩相连；将锁销（件13）插入，锁住弹簧秤手持端，将推钳总成07推到底，令防护盖板盖住弹簧末端挂钩部位及连接板；然后操纵者走到盖板后方，启动气缸操纵总裁（件09），控制进气速度，使气缸缓慢撑开。紧盯弹簧秤刻度即可。当ABS传感器在传感器支架中滑动时，读取弹簧秤刻度。由此，可检测ABS传感器与传感器支架之间的夹持力和拉脱力。测试摩擦预紧力\\n\\n3、整套设备重约55kg，下方分别装配一对止动轮和万向轮，以便运输移动。\\t\\n本案的优势在于：以气缸总成、直线轨和滑块的气动撑紧来替代人工拉拽测试；以ABS固定板和连接板替代连接传感器和弹簧秤的捆绑铁丝；同时，加装推钳总成和防护盖板，设计弹簧秤紧固锁销，用以避免潜在的工伤风险\\t\\n\\n五、本发明/实用新型的关键点和欲保护点是：\\n1、检测方式：用气动代替人力，以气缸总成、直线导轨、带弹簧秤安装支架的滑块气动撑紧来替代人工拉拽检测；。\\n2、紧固连接方式：设计专用ABS固定板，使其冲压形状安装后能够卡住传感器末端，以该固定板和带孔连接板替代连接传感器末端和弹簧秤的铁丝，提升操作效率。\\n3、安全性：加装推钳总成、树脂垫块和防护盖板，设计弹簧秤紧固锁销，用以避免潜在的工伤风险。\\n4、传感器支架安装座上的安装孔设计为圆孔和长圆孔结合，令其间距能涵盖目前所有平台和规格的传感器支架，方便更换安装。\\t\\n六、与第二条所属的最好的现有技术相比，本发明/实用新型的优点：\\n1、使用灵活、节省工时、降低检验人员数量及劳动强度\\n2、定位方便、快捷、可靠，并能够适用于多个平台不同的ABS传感器的检验工作。\\n3、解决并避免了工伤风险。\\t\\n\\n七、针对第四部分中的技术方案，是否还有别的替代方案？\\n暂无替代方案\\t\\n八、其他有助于专利代理人理解本技术的资料：\\n【注意】\\n代理人并不是技术专家，交底书需要尽量使代理人看懂，特别对于背景技术和详尽的技术方案，\\n对同一事物的叫法应统一，避免出现一种东西多种叫法。\\n沟通时，对于代理人的疑问应认真理解，要求补充的材料应及时补充。\\n专利法规定：\\n①专利必须是一个技术方案，应该阐述发明（实用新型）目的是通过什么技术方案来实现的，不能只有原理，也不能只做功能介绍；\\n交底书不能按功能写，应按步骤/层次写，即从步骤/层次角度扩展（以阶梯方式描述），使之逻辑清楚。若从功能角度写，则具有较多的介绍成分，使本发明（实用新型）的方法/系统分散，不易提炼本发明（实用新型）的核心。\\n②专利必须充分公开，以本领域技术人员不需付出创造性劳动即可实现为准。\\n"}', '[]', 'approved', 1, '2026-05-18T08:21:58.947Z', '2026-05-18T08:21:58.947Z');
INSERT INTO disclosure_documents (id, case_id, content_json, ai_suggestions, status, version, created_at, updated_at) VALUES ('4b318fbd-9788-458d-928b-a868ca4eb4b5', '06f2893a-979d-49ad-98e8-0adb6db60f47', '{"title":"生物化学：一种血液灌流器用改性聚苯乙烯吸附树脂及其制备方法-发明","content":"\\n医药技术交底书\\n交底书名称\\t用于特发性肺纤维化治疗的血液灌流器填料制备方法\\t\\n申请类型\\t√发明     □实用新型     □发明与实用新型同时申报\\t\\n发明人/设计人\\t\\t\\n技术联系人\\t\\t\\n电  话\\t\\t\\t\\t\\n知识产权负责人\\t\\t\\n电  话\\t\\t\\t\\t\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n1、相关技术背景（背景技术），与本发明最相近似的现有实现方案（现有技术）\\n血液灌流是将患者的血液引入装有固态吸附剂的灌流器中，通过吸附作用，清除血液中透析不能清除的外源性或内源性毒素、药物或代谢废物的一种血液净化技术。主要用于抢救药物和毒物中毒，也可与血液透析合用以清除慢性肾功能衰竭维持性透析患者体内的大分子毒素。\\n由于内部填充的固态吸附剂吸附剂材质均为聚苯乙烯树脂或活性炭，目前大多依赖于供应商的直接供应，使用者的自主研发较少，吸附剂所能吸附的物质类型有限，被吸附的物质分子量不能较为准确的控制，使得血液灌流器大多为非特异性吸附。血液灌流器在临床的使用过程中，经常会发生将某些致病物质有效吸附的同时，把分子量大小近似的其余体液成分也一并吸附的情况。这样会导致人体有益体液成分的丢失，引起一些潜在的健康风险。\\n目前有部分使用者对固态吸附剂作出了不同程度的修饰和再加工，但填料基材还是局限于树脂供应商的本身产品属性，在实际临床应用时难以灵活选择。现有的大多吸附剂供应商所提供的吸附剂填料基材批次间差异较大，生物相容性不稳定，填料与血液中有害物质的接触不完全，吸附效率不高。且由于现有的修饰或改性方法对树脂进行化学键的修饰时都会引入多种化学试剂，部分试剂有毒有害或化学性能不稳定，生物相容性的问题没有得到很好的解决。\\n\\n应提供一至几篇在组分、制备方法、效果及目的方面与本发明密切相关的对比资料，并简述其组分、制备方法、效果，客观地指出其不足之处及其原因，如提供不出具体的文章，也应对现有技术的水平、缺点和不足作一介绍。\\n\\n2、本发明技术方案的详细阐述\\n特发性肺纤维化（IPF）是一种慢性、进行性、纤维化性间质性肺炎，组织学和（或）胸部HRCT表现为普通型间质性肺炎（UIP），病因不清，好发于老年人。IPF诊断后中位生存期为2-3年，大多数病人表现为缓慢逐步可预见的肺功能下降。IPF不能治愈，临床上的治疗目的是延缓疾病进展，改善生活质量，延长生存期。临床治疗主要是抗纤维化治疗、非药物治疗、肺移植。抗纤维化治疗很重要的机制是抑制血小板衍化生长因子受体（PDGFR）、血管内皮生长因子受体（VEGFR）和成纤维细胞生长因子受体（FGFR）。布罗索尤单抗可特异性地结合血液中的FGFR，从而起到抗纤维化治疗，改善疾病进展的作用。然而单抗类药物进入体内的过敏、输注反应、全身性血管炎、自身免疫样综合征等相关副作用难以避免，某些患者由于难以耐受而停药，且非人源性单抗反复多次输注后体内会产生抗体，导致疗效下降。本发明通过在聚苯乙烯树脂颗粒上固定PDGFA单抗，制备成血液灌流器填料，血液中的PDGFA流经以本发明所制备固定化PDGFA单抗的聚苯乙烯树脂作为填料而制作的血液灌流器时，该填料树脂所固定的PDGFA单抗与PDGFA特异性结合，来降低血液中的PDGFA含量，从而达到治疗相关疾病的作用。\\n步骤：有几个步骤较之前提交的交底书有修改，需要注意一下\\n1、取粒径0.5-1.2mm的聚苯乙烯树脂15g，置于二氯甲烷（DCM）中搅拌浸泡4-6小时，再用溶液A（季戊四醇与蒸馏水体积比3:1配置成的溶液）洗滤2次。然后用常温蒸馏水和100℃蒸馏水分别洗滤5-10次，以除去聚苯乙烯树脂中的单体、残留低分子物和分散剂，用无水乙醇洗滤2次，真空干燥至恒重。将上述产物置于等离子镀膜机中，在射频13.56MHz，功率700-800W，流量350-400SCCM，氩气（Ar）等离子镀膜150min。镀膜完成后取出备用。（此步骤目的：聚苯乙烯树脂预处理及表面活化）该步骤中最核心最重要的条件是哪个？这些条件是能够直接影响该步骤能够成功的关键（二氯甲烷预处理树脂，季戊四醇对树脂进行表面活化，等离子镀膜机用来表面镀膜。活化和镀膜是关键）\\n2、在三颈瓶中加入邻苯二甲酸酐(PA)粉末和170ml溶液B（二氯甲烷与硝基苯体积比7.5:1配置成的溶液），超声振荡lOmin，然后加入步骤1所得到的处理后的聚苯乙烯树脂，向反应瓶中通纯氮5min后，在搅拌状态下加入适量AlCl3和邻苯二甲酸酐按比例混合成的催化剂（摩尔比，聚苯乙烯树脂: AlCl3: 邻苯二甲酸酐=1:2.5:1.5），再通纯氮5min后常压下反应10小时。反应完成后，将反应瓶中的反应物全部移至砂芯漏斗中，用1000ml 10%的稀盐酸洗滤30min，然后用蒸馏水洗至中性，再用足量四氢呋喃洗滤，最后用甲醇冲洗3次，真空干燥至恒重。（此步骤目的：聚苯乙烯树脂表面羧基化）该步骤中最核心最重要的条件是哪个？这些条件是能够直接影响该步骤能够成功的关键（核心条件是在搅拌状态下加入适量AlCl3和邻苯二甲酸酐按比例混合成的催化剂（摩尔比，聚苯乙烯树脂: AlCl3: 邻苯二甲酸酐=1:2.5:1.5））\\n\\n3、将步骤2所得产物用15mM MES 6.0清洗3次，并浸泡于150ml 15mM MES 6.0溶液中。取75mL浓度为20mg/ml的EDC，75ml浓度为24mg/ml的PEG-聚半胱氨酸-PLA，加入MES中，立即混匀，在25℃搅拌状态下反应30min。（此步骤目的：羧基偶联聚半胱氨酸）该步骤中最核心最重要的条件是哪个？这些条件是能够直接影响该步骤能够成功的关键（核心条件是75ml浓度为24mg/ml的PEG-聚半胱氨酸-PLA）\\n4、活化完成后将产物滤出，用足量冷的15mM MES 6.0溶液清洗3次，并浸泡于100ml 15mM MES 6.0溶液中，加入浓度为2mg/ml的PDGFA单抗450μL，在25℃混匀条件下，反应12-18小时。反应完成后将产物滤出，用缓冲液10mMPBS7.4+0.1%Tween20重复清洗2次，然后用蒸馏水清洗后加入1.5L缓冲液10mMPBS7.4+0.1%Tween20+0.1%BSA+0.01%Casein中，室温条件下混匀反应30min。反应完成后将产物滤出，水洗3次后真空干燥，得到表面固定有PDGFA单抗的改性聚苯乙烯树脂颗粒填料。（此步骤目的：固定PDGFA单抗）该步骤中最核心最重要的条件是哪个？这些条件是能够直接影响该步骤能够成功的关键（核心条件是浓度为2mg/ml的PDGFA单抗450μL，在25℃混匀条件下，反应12-18小时）\\n\\n\\n\\n以上4个步骤中的实验条件，哪些是影响改性聚苯乙烯树脂颗粒填料最终发挥清除血液毒素，降低血液中PDGFA含量效果的最重要的核心条件？\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n将所得产物作为填料装柱，组装成能特异性清除血液中PDGFA的血液灌流器。\\n\\n作为血液灌流器的填料装柱，用血浆进行PDGFA灌流效果测试：\\n\\n\\n此处的实验一、实验二、实验三分别指的是什么，请详细提供实验一、实验二、实验三的实验内容和条件。\\n\\n\\n\\n应当对自己的发明创造的技术内容进行全面介绍、详细描述。化合物类产品应提供其结构式及其鉴定方法，化合物的理化性质及其测定方法，并提供其用途及制备方法；组合物类产品应说明其化学组成、含量范围、各组份的作用等，并并提供组合物用途及制备方法；工艺方法类技术应写明其步骤，各步骤中所需要的条件，如温度、压力范围、酸碱度、时间及其它具体要求；中药类技术应给出各味药材的用量、主治、功效、毒理等，如果出自药典，请提供出处；并提供配方的制备方法、使用方法，即制备的粒度、粉碎方式、干燥方式、保存方式、冲服方式、注意事项等。\\n3、技术效果及优点\\n优点：\\n1、本发明所制得的表面固定有PDGFA单抗的改性填料树脂颗粒可特异性结合血液中的PDGF，扩大了以往血液灌流器的适应症范围，可对PDGF所诱导的特发性肺纤维化及相关疾病起到治疗作用；\\n2、与传统一次性使用血液灌流器填料相比，本发明填料运用邻苯二甲酸酐改性后的聚苯乙烯树脂颗粒表面枝接了PDGFA单抗，可高效清除血液中的PDGFA，对血液中的其他物质成分没有影响，特异性更强；\\n3、本发明中的血液灌流器填料基质利用了聚苯乙烯树脂颗粒填料的表面羧基化，将PDGFA单抗通过共价键牢固的固定在填料表面，避免脱落。反应条件温和，使PDGFA单抗得以保留最大的酶活；\\n4、本发明中的血液灌流器填料改性过程反应流程灵活可控，批次间差异小，对血液中有害物质的清除性能更稳定；\\n5、填料与血液中单一物质的反应更为高效，缩短整体血液灌流的治疗时间，减少治疗风险发生的可能性，提高医疗资源利用率，创造更大的经济效益和社会效益。\\n本发明与现有技术相比所具有的优点及效果（即克服了现有技术的什么缺点），请结合具体组分或工艺改进分析，并提供适当的实验或测定数据，或典型的治愈例子，在治愈例子内，请阐述姓名、年龄、性别、症状、病史、服药情况、治愈效果等。\\n\\n\\n\\n"}', '[]', 'approved', 1, '2026-05-18T08:21:59.729Z', '2026-05-18T08:21:59.729Z');
INSERT INTO disclosure_documents (id, case_id, content_json, ai_suggestions, status, version, created_at, updated_at) VALUES ('7ed7ba84-c0a3-4c78-8cff-2b74ca43f913', '6a78a198-85ed-4ed3-ad83-6bfa36b82ac5', '{"title":"一种水面漂浮定点自沉的救援系统","content":"一种水面漂浮定点自沉的救援系统\\n\\n根据信息监测、阻敌和人员救护需要，利用洋流的水流方向布设特定的水上漂浮筒。漂浮筒表面颜色采用海洋迷彩涂装，多个漂浮筒用绳索组合增加浮力。靠近锚端与配重的漂浮筒串联，并缠绕绳索。需要漂浮在水面的漂浮筒并联，增加浮力。由工作船在洋流上游充气后放漂，系统定位采用卫星定位、并向控制中心发送位置。在其到达特定位置后靠近锚链端的漂浮筒自爆或者脱离减小浮力，配重与锚链下沉，绳索展开。在滚筒中布置急救物资，在人员发现后可以利用，并发出带有位置的求救信息，以便救援人员定位识别后到达现场。在漂浮筒内存储特别救护物资，包括急救食物、药品、防晒、救生衣、信号弹等，便于求救人员向救援船、救援飞机等发射信号。\\n\\n\\n\\n系统由信息中心、控制系统、漂浮筒、系留绳索单元、锚与配重、GNSS、加密卫星通信、敌我识别系统、无线电音频输入装置、无线电音频输出装置、摄像机与云台、雷达等组成。信息中心由加密通信、GIS、深度学习模型等组成。利用传感器获取周围的船舶、人员、鱼群的信息，并利用目标移动轨迹分析，用于落水人员自我施救、阻拦敌人船舶、鱼汛等。\\n\\n根据需要在目标区域洋流的上游放漂多个漂浮筒单元，利用卫星定位、卫星通信、GIS监测漂浮桶的位置。根据漂浮筒的定位位置规划点和漂浮桶位置的距离控制其自沉的间隔和启动时刻。为什么要自沉？启动是什么意思？\\n\\n\\n\\n控制模块\\n\\n定位通信\\n\\n蓄电池\\n\\n海浪发电\\n\\n天线\\n\\n漂浮筒使用特定材料制成，具有良好的浮力，并且表面采用海洋迷彩涂装，以减少在海洋中的可见性。\\n\\n每个漂浮筒根据需要由若干个独立的气囊组成，气囊有独立的放气阀，利用电磁开关控制，需要减小浮力时电磁阀开启电磁阀开关放气，气囊内的气体在外部水压挤压下溢出，外部水吸入。或者利用自爆式装置破坏气囊，自爆装置的铁制外壳内密封有炸药、电雷管，引线密封防水。外壳爆炸时分裂为有尖锐的铁皮，可以划破气囊。根据需要设置多组自爆装置，可以用于阻敌和伤敌时控制引爆。\\n\\n在漂浮筒气囊的两侧对称分别设置配重、防水红外摄像机与雷达，配重在水中，以使得摄像头和雷达漂浮在水面上，可以扫描海面，并利用云台旋转摄像机。红外摄像机和雷达连接到控制系统，控制系统有卫星定位芯片、卫星通信芯片。控制系统把采集到信息进行简单处理后，上传至信息中心。\\n\\n系统采用防水密封，保证系统在水面能持续工作。\\n\\n为了在紧急情况下能够及时发出求救信号和与救援人员进行通信，救援系统配置相应的信号和通信设备，例如蜂鸣器、闪光灯、无线电通信等。\\n\\nGNSS与卫星通信芯片外接天线，固定在漂浮筒外侧面，增强信号。敌我识别系统利用特定频率的无线电信号进行联系，人员手持机发送验证码，漂浮筒内的接收验证码，如果通过验证，则为己方人员。\\n\\n漂浮筒的浮力，要大于绳索、锚、配重的重量，以能随洋流漂浮。\\n\\n配重的质量根据实际每个漂浮筒单元的浮力需求进行调整，以确保系统在洋流中漂浮的稳定性。同时，自沉时部分漂浮筒放气，配重与锚钩下沉。需要漂浮筒露出水面时的浮力要大于等于配重和锚钩的质量，利用锚钩和配重的重量平衡浮力，依靠锚钩附着力定位，避免配重和锚钩被票浮筒拖曳离开锚地。如果需要漂浮筒潜于水面下，则漂浮筒的浮力要小于锚钩与配重的重量，同时漂浮筒潜于水面下受水挤压，浮力变小，依靠锚钩与配重的重量以及锚钩的附着力把漂浮筒悬浮在水中。\\n\\n信息中心建立GIS图，根据每个漂浮筒单元发回的位置信息，在中心GIS中标注漂浮筒的速度、位置，根据信息采集布点规划需要，从漂浮至最远处的漂浮筒开始控制自沉。漂流在最前的浮筒与规划最远布设点的距离最近，根据由近及远开启自沉，防止流经的漂浮筒的锚钩划破已经自沉的筒组或者缠绕绳索。\\n\\n根据漂浮筒释放位置可能漂流到的最远目标规划点位置与已经漂流到需要启动自沉的距离、漂浮速度，预测其到达规划点的时间；\\n\\n\\n\\nL, 预备自沉的目标规划点位置与漂浮筒的距离。\\n\\nv,漂浮筒的漂流速度。\\n\\n根据自沉时间与漂流速度确定启动自沉的距离：\\n\\n\\n\\n根据每个漂浮筒单元发送至信息中心的漂浮信息，在GIS中标注其位置，记录其漂流轨迹，记录并分析其漂流的速度，在距离L<时，启动该漂浮筒的自沉程序。\\n\\n系留绳索单元由漂浮筒、驱动电机、缠绕筒、系留绳索组成。驱动电机与缠绕筒同轴安装，固定在漂浮筒的轴向上，系留绳索一端固定在轴上，另一端从侧面穿出漂流筒。\\n\\n\\n\\nv\\n\\ntz\\n\\nLz\\n\\n自沉点\\n\\nL\\n\\n系留绳索的长度储备以目标点的最大水深为基准，释放过程中，靠近锚和重物的浮筒依次放气或自爆，如果漂浮筒继续漂移，则说明锚没有触底，需要继续释放绳索。如果漂流速度变慢，说明已经锚触底并固定。\\n\\n如果需要漂浮筒露出水面，则系留绳索的长度要大于水深。如果需要漂浮筒潜于水面下，则系留绳索的长度要小于水深，依靠锚钩与配重的重量，以及锚钩的附着力把漂浮筒悬浮在水中。\\n\\n\\n\\n系留绳索可以采用定长，根据规划锚地的水深预设符合漂浮筒位置的绳索长度。可以在漂浮筒内部设置缠绕筒，在锚钩与配重的漂浮筒放气后下沉时利用重力牵引施放绳索。如果需要改变绳索的长度，可以在缠绕筒端布设旋转电机，通过控制电机的正反转带动缠绕筒施放或者收缠绳索，从而控制漂浮筒与锚地的距离。在信息中心接到人员求救信号后，定位人员的位置，分析与其最近的漂浮筒的位置、距离及是否能游泳或漂浮达到。如果近距离可以漂浮到达，远距离漂浮或者游泳较为困难，则释放最近的上游漂浮筒的系留绳索，让漂浮筒快速漂流至人员处。\\n\\n\\n\\n锚触底\\n\\n位置判断\\n\\n位置稳定？\\n\\n地图匹配\\n\\n卫星通信\\n\\nGNSS\\n\\n是\\n\\n否\\n\\n标注位置\\n\\n监测漂浮筒的如果漂浮筒返回的位置处于一个包络线内，则说明锚触底。漂浮筒在水面受风、洋流、涌浪、水面高度等影响，定位位置以锚为中心在包络面内漂移。\\n\\n在漂流过程中，可以利用漂浮筒的摄像机、雷达监测沿途的情况，利用相互的位置、监测信息判断漂浮筒的间隔及信息。\\n\\n在漂浮筒自沉锚定后，漂浮筒的摄像机和雷达监测设计范围内的信息。在有人员落水后，利用信息中心的GIS，寻找就近的漂浮筒。\\n\\n信息中心对摄像机和雷达返回的信息进行处理，以期发现需要分析的船舶、漂浮物等目标的特征图像训练深度学习模型，分别处理分析每个漂浮筒单元发挥的信息。\\n\\n根据需要，在漂浮筒内布设远程可控的爆炸物，\\n\\n\\n\\n\\n\\n蓄电池\\n\\n海浪发电\\n\\n异常图像？\\n\\n云台\\n\\n红外\\n\\nGNSS\\n\\n控制系统\\n\\n卫星通信\\n\\n信息中心\\n\\n摄像机\\n\\n是\\n\\n否\\n\\n漂浮筒的规划布设点不宜太密集，预防相邻的漂浮筒的绳索交织。\\n\\n水太深的地方，系留漂浮筒的绳索太长，成本较高。首先根据洋流的水流方向和监测落水者信息，选择合适的位置布设漂浮筒。漂浮筒采用海洋迷彩涂装，多个漂浮筒通过绳索组合增加浮力，并且需要进行并联布置以增加浮力。\\n\\n放置在水上后会向控制中心发送位置信息，确保救援人员可以准确获取落水者其位置信息。\\n\\n漂浮筒摄像头360°环顾，在拍摄并分析落水者后，通过敌我识别判断敌友，使检测落水者周边水域情况，己方人员则通过无线电音频装置与落水者对话，从而帮助落水者进行救援队救援前的自我救助。落水者也可以向救援船、救援飞机等发射信号，同时发出带有位置信息的求救信息。敌方人员则语音喊话劝其投降，在投降后可以允许其使用救生器材，如果拒不投降，则引爆漂浮筒里的自爆箱伤敌或发送敌人信息至信息中心。\\n\\n漂浮筒：使用特定材料制成，具有良好的浮力，并且表面采用海洋迷彩涂装，以减少在海洋中的可见性，避免被地方航测容易发现。\\n\\n绳索：用于将多个漂浮筒串联并固定在一起，以增加整体的浮力。绳索应该具备足够的强度和耐久性，以承受海洋环境的影响。\\n\\n配重：用于漂浮筒系统的稳定性和下沉，配重应根据实际情况进行设计和调整，以确保系统在洋流中的稳定性。\\n\\n锚链：用于固定漂浮筒系统的位置，锚链应具备足够的强度和耐腐蚀性，以应对海洋环境的挑战。\\n\\n卫星定位系统：用于定位漂浮筒系统的位置，可以使用全球定位系统（GPS）或其他卫星定位技术来实现。\\n\\n控制中心：接收漂浮筒系统的位置信息，并负责监控和管理救援行动。\\n\\n滚筒：用于布置急救物资，滚筒应具有防水和防潮的特性，以保护物资的完整性。\\n\\n救援物资：包括急救食物、药品、防晒用品、救生衣、信号弹等，这些物资应储存在漂浮筒内，以供求救人员使用。\\n\\n以上是一种可能的配置方案，具体的实现方式可以根据实际需求和资源进行调整和优化。在设计和操作过程中，应充分考虑海洋环境的复杂性和安全性要求，确保装置能够有效地发挥救援作用。\\n\\n"}', '[]', 'approved', 1, '2026-05-18T08:22:00.038Z', '2026-05-18T08:22:00.038Z');

